import{_ as e,C as a,c as t,o,j as s,b as i,a0 as r,a as d,w as n,G as l,a1 as u}from"./chunks/framework.DKRgXLPU.js";const m=JSON.parse('{"title":"Criando seu plano de treinamento","description":"","frontmatter":{},"headers":[],"relativePath":"pt/education/goals/planning.md","filePath":"pt/education/goals/planning.md"}');const c=e({name:"pt/education/goals/planning.md"},[["render",function(e,m,c,p,h,g){const b=a("Mermaid");return o(),t("div",null,[m[1]||(m[1]=s("h1",{id:"criando-seu-plano-de-treinamento",tabindex:"-1"},[d("Criando seu plano de treinamento "),s("a",{class:"header-anchor",href:"#criando-seu-plano-de-treinamento","aria-label":'Permalink to "Criando seu plano de treinamento"'},"​")],-1)),m[2]||(m[2]=s("p",null,"Metas sem um plano são apenas desejos. Este guia ajuda você a transformar suas metas em um plano de treinamento estruturado que realmente funciona.",-1)),m[3]||(m[3]=s("div",{class:"tip custom-block"},[s("p",{class:"custom-block-title"},"A Grande Ideia"),s("p",null,[s("strong",null,"Objetivos sem um plano são apenas desejos."),d(" Um plano de treinamento estruturado transforma seus objetivos em ações diárias que se acumulam e resultam em progresso real.")])],-1)),(o(),i(u,null,{default:n(()=>[l(b,{id:"mermaid-11",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BMeta%5D%20--%3E%20B%5BPlano%20de%20Treinamento%5D%0A%20%20%20%20B%20--%3E%20C%5BA%C3%A7%C3%B5es%20di%C3%A1rias%5D%0A%20%20%20%20C%20--%3E%20D%5BPr%C3%A1tica%20consistente%5D%0A%20%20%20%20D%20--%3E%20E%5BProgresso%20mensur%C3%A1vel%5D%0A%20%20%20%20E%20--%3E%20F%5BConquista%20de%20Objetivos%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20B%20fill%3A%23e8f5e9%0A%20%20%20%20style%20C%20fill%3A%23fff4e1%0A%20%20%20%20style%20F%20fill%3A%23fff4e1%0A"})]),fallback:n(()=>[...m[0]||(m[0]=[d(" Loading... ",-1)])]),_:1})),m[4]||(m[4]=r('<h2 id="as-8-fases-do-desenvolvimento-autodirigido" tabindex="-1">As 8 fases do desenvolvimento autodirigido <a class="header-anchor" href="#as-8-fases-do-desenvolvimento-autodirigido" aria-label="Permalink to &quot;As 8 fases do desenvolvimento autodirigido&quot;">​</a></h2><h3 id="fase-1-defina-sua-bussola-objetivos" tabindex="-1">Fase 1: Defina sua bússola (Objetivos) <a class="header-anchor" href="#fase-1-defina-sua-bussola-objetivos" aria-label="Permalink to &quot;Fase 1: Defina sua bússola (Objetivos)&quot;">​</a></h3><p>Você já aprendeu sobre metas SMART. Agora, organize-as em uma hierarquia:</p><ol><li><strong>Objetivo a longo prazo</strong> (1 a 2 anos): Seu sonho</li><li><strong>Meta anual</strong>: Meta para este ano</li><li><strong>Metas trimestrais</strong>: marcos trimestrais</li><li><strong>Metas mensais</strong>: Áreas de foco específicas</li><li><strong>Objetivos semanais</strong>: Metas de treinamento</li></ol><h3 id="fase-2-avalie-seus-recursos" tabindex="-1">Fase 2: Avalie seus recursos <a class="header-anchor" href="#fase-2-avalie-seus-recursos" aria-label="Permalink to &quot;Fase 2: Avalie seus recursos&quot;">​</a></h3><p>Antes de planejar, avalie honestamente o que você tem:</p><table tabindex="0"><thead><tr><th>Recurso</th><th>Perguntas a fazer</th></tr></thead><tbody><tr><td><strong>Tempo</strong></td><td>Quantas horas por semana você consegue treinar de forma realista?</td></tr><tr><td><strong>Localização</strong></td><td>Você tem acesso a uma pista adequada? Qual é a qualidade da superfície?</td></tr><tr><td><strong>Equipamento</strong></td><td>Você tem bolas de bocha adequadas? Ferramentas de medição? Capacidade de filmagem?</td></tr><tr><td><strong>Conhecimento</strong></td><td>Quais são seus pontos fortes e fracos em termos técnicos?</td></tr><tr><td><strong>Condição física</strong></td><td>Há alguma limitação? Alguma área que precise de melhorias?</td></tr></tbody></table><p>Seja honesto. Um plano realista é melhor do que uma fantasia ambiciosa.</p><h3 id="fase-3-escolha-seus-exercicios" tabindex="-1">Fase 3: Escolha seus exercícios <a class="header-anchor" href="#fase-3-escolha-seus-exercicios" aria-label="Permalink to &quot;Fase 3: Escolha seus exercícios&quot;">​</a></h3><p>Selecione exercícios que contribuam diretamente para seus objetivos:</p><p><strong>Para melhorar a pontuação:</strong></p><ul><li>Apontamento preciso para zonas marcadas</li><li>exercícios de variação de distância</li><li>Prática de superfície diferente</li></ul><p><strong>Para melhorar a sua pontaria:</strong></p><ul><li>Escada de tiro (distâncias progressivas)</li><li>Tiro ao obstáculo (arco alto forçado)</li><li>prática de alvo móvel</li></ul><p><strong>Para o desenvolvimento mental:</strong></p><ul><li>prática de rotina pré-arremesso</li><li>Sessões de visualização</li><li>Simulação de pressão</li></ul><p><strong>Equilibre seu programa:</strong></p><ul><li>Trabalho técnico (apontar, disparar)</li><li>Treinamento mental (atenção plena, visualização)</li><li>Condicionamento físico (equilíbrio, flexibilidade)</li><li>Jogo de partidas (aplicação de habilidades)</li></ul><h3 id="fase-4-crie-seu-cronograma" tabindex="-1">Fase 4: Crie seu cronograma <a class="header-anchor" href="#fase-4-crie-seu-cronograma" aria-label="Permalink to &quot;Fase 4: Crie seu cronograma&quot;">​</a></h3><p>Elabore um cronograma semanal realista:</p><table tabindex="0"><thead><tr><th>Dia</th><th>Manhã</th><th>Tarde</th><th>Noite</th><th>Foco</th></tr></thead><tbody><tr><td>seg</td><td>-</td><td>Técnico: Apontar</td><td>Mobilidade leve</td><td>Precisão</td></tr><tr><td>ter</td><td>-</td><td>Técnico: Tiro ao alvo</td><td>-</td><td>Potência/precisão</td></tr><tr><td>qua</td><td>-</td><td>Treinamento mental</td><td>-</td><td>Atenção plena</td></tr><tr><td>qui</td><td>-</td><td>Misto: Cenários de jogo</td><td>Mobilidade leve</td><td>Aplicativo</td></tr><tr><td>sex</td><td>-</td><td>Técnico: Fraqueza</td><td>-</td><td>Melhoria</td></tr><tr><td>Sentado</td><td>Jogo ou competição</td><td>-</td><td>-</td><td>Desempenho</td></tr><tr><td>Sol</td><td>Descansar</td><td>Revisão semanal</td><td>Planejamento</td><td>Recuperação</td></tr></tbody></table><p><strong>Princípios fundamentais:</strong></p><ul><li>Priorize o treinamento mental (ele costuma ser negligenciado).</li><li>Incluir dias de descanso</li><li>Equilibrar diferentes habilidades</li><li>Deixe a flexibilidade para a vida</li></ul><h3 id="fase-5-preparar-se-para-os-obstaculos" tabindex="-1">Fase 5: Preparar-se para os obstáculos <a class="header-anchor" href="#fase-5-preparar-se-para-os-obstaculos" aria-label="Permalink to &quot;Fase 5: Preparar-se para os obstáculos&quot;">​</a></h3><p>As coisas vão dar errado. Esteja preparado para isso.</p><table tabindex="0"><thead><tr><th>Risco</th><th>Probabilidade</th><th>Impacto</th><th>Plano de contingência</th></tr></thead><tbody><tr><td>Falta de tempo</td><td>Alto</td><td>Médio</td><td>Tenha uma &quot;sessão mínima&quot; preparada (20 minutos).</td></tr><tr><td>Mau tempo</td><td>Médio</td><td>Médio</td><td>Visualização em ambientes internos, estudo em vídeo</td></tr><tr><td>Baixa motivação</td><td>Alto</td><td>Médio</td><td>Retorne ao &quot;porquê&quot;, estabeleça metas menores e faça uma pausa.</td></tr><tr><td>Lesão leve</td><td>Médio</td><td>Alto</td><td>Foque no treinamento mental e em habilidades não afetadas.</td></tr><tr><td>Sem parceiro de treino</td><td>Médio</td><td>Baixo</td><td>Exercícios individuais, autoanálise em vídeo</td></tr></tbody></table><h3 id="fase-6-acompanhe-seu-progresso" tabindex="-1">Fase 6: Acompanhe seu progresso <a class="header-anchor" href="#fase-6-acompanhe-seu-progresso" aria-label="Permalink to &quot;Fase 6: Acompanhe seu progresso&quot;">​</a></h3><p>O que é medido é gerenciado.</p><p><strong>Mantenha um diário de treinamento:</strong></p><ul><li>Data e duração</li><li>Exercícios concluídos</li><li>Pontuações/resultados</li><li>Como você se sentiu (energia, foco, estado de fluxo)</li><li>Notas técnicas</li><li>Clima/condições</li></ul><p><strong>Questões de revisão semanais:</strong></p><ul><li>Concluí as sessões que havia planejado?</li><li>Que pontuação eu obtive?</li><li>O que foi agradável? O que foi difícil?</li><li>Alguém já passou por uma experiência de estado de fluxo?</li><li>O que devo ajustar?</li></ul><h3 id="fase-7-mantenha-se-motivado" tabindex="-1">Fase 7: Mantenha-se motivado <a class="header-anchor" href="#fase-7-mantenha-se-motivado" aria-label="Permalink to &quot;Fase 7: Mantenha-se motivado&quot;">​</a></h3><p>A motivação oscila. Crie sistemas para mantê-la:</p><p><strong>Motivação interna:</strong></p><ul><li>Conecte-se ao seu &quot;porquê&quot;</li><li>Comemore as pequenas vitórias</li><li>Observe a melhora ao longo do tempo.</li><li>Encontre alegria no processo.</li></ul><p><strong>Suporte externo:</strong></p><ul><li>Parceiros de treino (mesmo que ocasionalmente)</li><li>Compartilhe seus objetivos com alguém.</li><li>Participe de comunidades online</li><li>Acompanhe as sequências e a consistência.</li></ul><p><strong>Quando a motivação diminui:</strong></p><ul><li>Faça uma sessão mínima (qualquer coisa é melhor do que nada).</li><li>Mude seu ambiente</li><li>Analise seu progresso</li><li>Lembre-se dos sucessos passados</li><li>Faça uma pausa planejada, se necessário.</li></ul><h3 id="fase-8-revisao-e-adaptacao" tabindex="-1">Fase 8: Revisão e Adaptação <a class="header-anchor" href="#fase-8-revisao-e-adaptacao" aria-label="Permalink to &quot;Fase 8: Revisão e Adaptação&quot;">​</a></h3><p>Seu plano deve evoluir:</p><p><strong>Semanalmente:</strong> Revisão rápida, ajustes menores <strong>Mensalmente:</strong> Avaliar o progresso em relação às metas mensais e ajustar o foco. <strong>Trimestral:</strong> Revisão geral, definição das metas para o próximo trimestre. <strong>Anualmente:</strong> Avaliação completa, novo plano anual</p><p><strong>Questões para revisão:</strong></p><ul><li>Estou progredindo em direção aos meus objetivos?</li><li>Meu treinamento é eficaz?</li><li>Preciso de exercícios diferentes?</li><li>Meus objetivos ainda são relevantes?</li><li>O que eu aprendi?</li></ul><h2 id="exemplo-de-plano-de-8-semanas" tabindex="-1">Exemplo de Plano de 8 Semanas <a class="header-anchor" href="#exemplo-de-plano-de-8-semanas" aria-label="Permalink to &quot;Exemplo de Plano de 8 Semanas&quot;">​</a></h2><p><strong>Objetivo:</strong> Melhorar a precisão dos arremessos em 15%</p><table tabindex="0"><thead><tr><th>Semana</th><th>Foco</th><th>Sessões principais</th></tr></thead><tbody><tr><td>1</td><td>Linha de base</td><td>Teste o nível atual, análise de vídeo</td></tr><tr><td>2</td><td>Técnica</td><td>Identificar e trabalhar nas questões principais</td></tr><tr><td>3</td><td>Repetição</td><td>Prática de tiro em alto volume</td></tr><tr><td>4</td><td>Teste</td><td>Avaliação intermediária, ajuste</td></tr><tr><td>5</td><td>Variação</td><td>Distâncias e ângulos diferentes</td></tr><tr><td>6</td><td>Pressão</td><td>Adicionar consequências aos exercícios</td></tr><tr><td>7</td><td>Integração</td><td>Cenários semelhantes a jogos</td></tr><tr><td>8</td><td>Teste final</td><td>Melhoria da mensuração</td></tr></tbody></table><h2 id="ponto-chave" tabindex="-1">Ponto-chave <a class="header-anchor" href="#ponto-chave" aria-label="Permalink to &quot;Ponto-chave&quot;">​</a></h2><blockquote><p>Planeje seu trabalho e depois execute o plano. Mas esteja preparado para se adaptar.</p></blockquote><p>O melhor plano é aquele que você realmente segue. Comece com algo simples, mantenha a consistência e ajuste conforme for aprendendo.</p>',51))])}]]);export{m as __pageData,c as default};
